## [Hono Integration](https://better-auth.com/docs/integrations/hono)

# Hono Integration
## [CORS](https://better-auth.com/docs/integrations/hono#cors)
```
import { Hono } from "hono";
import { cors } from "hono/cors";
import { auth } from "./auth";

const app = new Hono();

app.use(
	"/api/auth/*",
	cors({
		origin: "http://localhost:3001",
		credentials: true,
	}),
);

app.all("/api/auth/*", (c) => auth.handler(c.req.raw));

export default app;
```

```
import { betterAuth } from "better-auth";

export const auth = betterAuth({
	trustedOrigins: ["http://localhost:3001"],
});
```

## [Middleware](https://better-auth.com/docs/integrations/hono#middleware)
```
import { createMiddleware } from "hono/factory";
import { auth } from "./auth";

type Env = {
	Variables: {
		session: typeof auth.$Infer.Session | null;
	};
};

export const sessionMiddleware = createMiddleware<Env>(async (c, next) => {
	const session = await auth.api.getSession({
		headers: c.req.raw.headers,
	});

	c.set("session", session);

	await next();
});
```

```
import { Hono } from "hono";
import { HTTPException } from "hono/http-exception";
import { sessionMiddleware } from "./session-middleware";

const app = new Hono();

app.get("/hello", sessionMiddleware, (c) => {
	const session = c.get("session");

	if (!session) {
		throw new HTTPException(401);
	}

	return c.json({ message: `Hello, ${session.user.name}.` });
});

export default app;
```

